protected void setCursorPosition(float x, float y) {
    cursor = letterUnderCursor(x);
    cursorOn = focused;
    blinkTask.cancel();
    if (focused)
        Timer.schedule(blinkTask, blinkTime, blinkTime);
}

protected void goHome(boolean jump) {
    cursor = 0;
}

protected void goEnd(boolean jump) {
    cursor = text.length();
}

public boolean keyDown(InputEvent event, int keycode) {
    if (disabled)
        return false;
    cursorOn = focused;
    blinkTask.cancel();
    if (focused)
        Timer.schedule(blinkTask, blinkTime, blinkTime);
    if (!hasKeyboardFocus())
        return false;
    boolean repeat = false;
    boolean ctrl = UIUtils.ctrl();
    boolean jump = ctrl && !passwordMode;
    boolean handled = true;
    if (ctrl) {
        switch(keycode) {
            case Keys.V:
                paste(clipboard.getContents(), true);
                repeat = true;
                break;
            case Keys.C:
            case Keys.INSERT:
                copy();
                return true;
            case Keys.X:
                cut(true);
                return true;
            case Keys.A:
                selectAll();
                return true;
            case Keys.Z:
                String oldText = text;
                setText(undoText);
                undoText = oldText;
                updateDisplayText();
                return true;
            default:
                handled = false;
        }
    }
    if (UIUtils.shift()) {
        switch(keycode) {
            case Keys.INSERT:
                paste(clipboard.getContents(), true);
                break;
            case Keys.FORWARD_DEL:
                cut(true);
                break;
        }
        selection: {
            int temp = cursor;
            keys: {
                switch(keycode) {
                    case Keys.LEFT:
                        moveCursor(false, jump);
                        repeat = true;
                        handled = true;
                        break keys;
                    case Keys.RIGHT:
                        moveCursor(true, jump);
                        repeat = true;
                        handled = true;
                        break keys;
                    case Keys.HOME:
                        goHome(jump);
                        handled = true;
                        break keys;
                    case Keys.END:
                        goEnd(jump);
                        handled = true;
                        break keys;
                }
                break selection;
            }
            if (!hasSelection) {
                selectionStart = temp;
                hasSelection = true;
            }
        }
    } else {
                switch(keycode) {
            case Keys.LEFT:
                moveCursor(false, jump);
                clearSelection();
                repeat = true;
                handled = true;
                break;
            case Keys.RIGHT:
                moveCursor(true, jump);
                clearSelection();
                repeat = true;
                handled = true;
                break;
            case Keys.HOME:
                goHome(jump);
                clearSelection();
                handled = true;
                break;
            case Keys.END:
                goEnd(jump);
                clearSelection();
                handled = true;
                break;
        }
    }
    cursor = MathUtils.clamp(cursor, 0, text.length());
    if (repeat)
        scheduleKeyRepeatTask(keycode);
    return handled;
}

protected void scheduleKeyRepeatTask(int keycode) {
    if (!keyRepeatTask.isScheduled() || keyRepeatTask.keycode != keycode) {
        keyRepeatTask.keycode = keycode;
        keyRepeatTask.cancel();
        Timer.schedule(keyRepeatTask, keyRepeatInitialTime, keyRepeatTime);
    }
}

public boolean keyUp(InputEvent event, int keycode) {
    if (disabled)
        return false;
    keyRepeatTask.cancel();
    return true;
}


protected boolean checkFocusTraversal(char character) {
    return focusTraversal && (character == TAB || ((character == CARRIAGE_RETURN || character == NEWLINE) && (UIUtils.isAndroid || UIUtils.isIos)));
}

public boolean keyTyped(InputEvent event, char character) {
    if (disabled)
        return false;
        switch(character) {
        case BACKSPACE:
        case TAB:
        case NEWLINE:
        case CARRIAGE_RETURN:
            break;
        default:
            if (character < 32)
                return false;
    }
    if (!hasKeyboardFocus())
        return false;
    if (UIUtils.isMac && Gdx.input.isKeyPressed(Keys.SYM))
        return true;
    if (checkFocusTraversal(character))
        next(UIUtils.shift());
    else {
        boolean enter = character == CARRIAGE_RETURN || character == NEWLINE;
        boolean delete = character == DELETE;
        boolean backspace = character == BACKSPACE;
        boolean add = enter ? writeEnters : (!onlyFontChars || style.font.getData().hasGlyph(character));
        boolean remove = backspace || delete;
        if (add || remove) {
            String oldText = text;
            int oldCursor = cursor;
            if (remove) {
                if (hasSelection)
                    cursor = delete(false);
                else {
                    if (backspace && cursor > 0) {
                        text = text.substring(0, cursor - 1) + text.substring(cursor--);
                        renderOffset = 0;
                    }
                    if (delete && cursor < text.length()) {
                        text = text.substring(0, cursor) + text.substring(cursor + 1);
                    }
                }
            }
            if (add && !remove) {
                                if (!enter && filter != null && !filter.acceptChar(TextField.this, character))
                    return true;
                if (!withinMaxLength(text.length() - (hasSelection ? Math.abs(cursor - selectionStart) : 0)))
                    return true;
                if (hasSelection)
                    cursor = delete(false);
                String insertion = enter ? "\n" : String.valueOf(character);
                text = insert(cursor++, insertion, text);
            }
            String tempUndoText = undoText;
            if (changeText(oldText, text)) {
                long time = System.currentTimeMillis();
                if (time - 750 > lastChangeTime)
                    undoText = oldText;
                lastChangeTime = time;
                updateDisplayText();
            } else if (            !text.equals(oldText))
                cursor = oldCursor;
        }
    }
    if (listener != null)
        listener.keyTyped(TextField.this, character);
    return true;
}

