private int toGdxButton(int button) {
    if (button == 0)
        return Buttons.LEFT;
    if (button == 1)
        return Buttons.RIGHT;
    if (button == 2)
        return Buttons.MIDDLE;
    if (button == 3)
        return Buttons.BACK;
    if (button == 4)
        return Buttons.FORWARD;
    return -1;
}

private int toLwjglButton(int button) {
    switch(button) {
        case Buttons.LEFT:
            return 0;
        case Buttons.RIGHT:
            return 1;
        case Buttons.MIDDLE:
            return 2;
        case Buttons.BACK:
            return 3;
        case Buttons.FORWARD:
            return 4;
    }
    return 0;
}

