@Test
public void keys() {
    test(    "{a:1,b:2,c:3}",     "()[]", "[a,b,c]");
    test(    "{a:1,b:2,c:3}",     "()[],(b)", "{\"\":[a,b,c]}");
    test(    "{a:1,b:2,c:3}",     "()[],(b)", "{\"\":[a,b,c]}");
    test(    "{object:{a:1,b:2,c:3}}",     "object/()[]", "[a,b,c]");
    test(    "{a:1,b:2,c:3}",     "()",     "a");
    test(    "{object:{a:1,b:2,c:3}}",     "object/()",     "a");
    test(    "[a,b,c]", "()[]");
    test(    "{object:{a:1,b:2,c:3}}",     "*/()[]", "[a,b,c]");
    test(    "{object:{a:1,b:2,c:{d:{e:3},f:[1,2,3]}}}",     "**/()[]",     "[object,a,b,c,d,e,f]");
}

@Test
public void earlyEnd() {
    test(    "extra", "{first:{id:1},second:{data:ignored},extra:should-not-parse}", new String[] {     "first/(id@)", "(second)" }, "1", "{data:ignored}");
    test(    "extra", "{first:{id:1},second:{id:ignored},extra:should-not-parse}", new String[] {     "*/(id@)", "*/(id)" }, "1", "1");
    test(    "extra", "{first:{id:1},second:{id:ignored},extra:should-not-parse}", new String[] {     "(first,second)@" }, "{id:1}", "{id:ignored}");
    test(    "extra", "{first:{id:1},second:{id:ignored},extra:should-not-parse}", new String[] {     "second/(id@)" }, "ignored");
    test(    "extra", "{first:{id:1},second:{id:ignored},third:{other:1},extra:should-not-parse}", new String[] {     "(first,second)@", "*/(other)" }, "{id:1}", "{id:ignored}", "1");
    test(    "extra", "{value:1,nested:{value:2},extra:{value:3}}", new String[] {     "(value@),*/(value@)" }, "1", "2");
}

