private Mono<InternalPartitionsOffsets> getPartitionOffsets(Map<String, TopicDescription> descriptionsMap, ReactiveAdminClient ac) {
    var descriptions = descriptionsMap.values();
    return ac.listOffsets(descriptions, OffsetSpec.earliest()).zipWith(ac.listOffsets(descriptions, OffsetSpec.latest()), (earliest, latest) -> Sets.intersection(earliest.keySet(), latest.keySet()).stream().map(tp -> Map.entry(tp, new InternalPartitionsOffsets.Offsets(earliest.get(tp), latest.get(tp)))).collect(toMap(Map.Entry::getKey, Map.Entry::getValue))).map(InternalPartitionsOffsets::new);
}

private Map<TopicPartition, Optional<NewPartitionReassignment>> getPartitionsReassignments(KafkaCluster cluster, InternalTopic topic, ReplicationFactorChangeDTO replicationFactorChange) {
        Map<Integer, List<Integer>> currentAssignment = getCurrentAssignment(topic);
        Map<Integer, Integer> brokersUsage = getBrokersMap(cluster, currentAssignment);
    int currentReplicationFactor = topic.getReplicationFactor();
        if (replicationFactorChange.getTotalReplicationFactor() > currentReplicationFactor) {
                for (var assignmentList : currentAssignment.values()) {
                        var brokers = brokersUsage.entrySet().stream().sorted(Map.Entry.comparingByValue()).map(Map.Entry::getKey).collect(toList());
                        for (Integer broker : brokers) {
                if (!assignmentList.contains(broker)) {
                    assignmentList.add(broker);
                    brokersUsage.merge(broker, 1, Integer::sum);
                }
                if (assignmentList.size() == replicationFactorChange.getTotalReplicationFactor()) {
                    break;
                }
            }
            if (assignmentList.size() != replicationFactorChange.getTotalReplicationFactor()) {
                throw new ValidationException("Something went wrong during adding replicas");
            }
        }
    } else if (replicationFactorChange.getTotalReplicationFactor() < currentReplicationFactor) {
        for (Map.Entry<Integer, List<Integer>> assignmentEntry : currentAssignment.entrySet()) {
            var partition = assignmentEntry.getKey();
            var brokers = assignmentEntry.getValue();
                        var brokersUsageList = brokersUsage.entrySet().stream().sorted(Map.Entry.comparingByValue(Comparator.reverseOrder())).map(Map.Entry::getKey).collect(toList());
                        for (Integer broker : brokersUsageList) {
                                if (!topic.getPartitions().get(partition).getLeader().equals(broker)) {
                    brokers.remove(broker);
                    brokersUsage.merge(broker, -1, Integer::sum);
                }
                if (brokers.size() == replicationFactorChange.getTotalReplicationFactor()) {
                    break;
                }
            }
            if (brokers.size() != replicationFactorChange.getTotalReplicationFactor()) {
                throw new ValidationException("Something went wrong during removing replicas");
            }
        }
    } else {
        throw new ValidationException("Replication factor already equals requested");
    }
        return currentAssignment.entrySet().stream().collect(toMap(e -> new TopicPartition(topic.getName(), e.getKey()), e -> Optional.of(new NewPartitionReassignment(e.getValue()))));
}

private Map<Integer, List<Integer>> getCurrentAssignment(InternalTopic topic) {
    return topic.getPartitions().values().stream().collect(toMap(InternalPartition::getPartition, p -> p.getReplicas().stream().map(InternalReplica::getBroker).collect(toList())));
}

