private List<AclBinding> createAllowBindings(ResourceType resourceType, List<AclOperation> opsToAllow, String principal, String host, @Nullable String resourcePrefix, @Nullable Collection<String> resourceNames) {
    List<AclBinding> bindings = new ArrayList<>();
    if (resourcePrefix != null) {
        for (var op : opsToAllow) {
            bindings.add(new AclBinding(new ResourcePattern(resourceType, resourcePrefix, PREFIXED), new AccessControlEntry(principal, host, op, ALLOW)));
        }
    }
    if (!CollectionUtils.isEmpty(resourceNames)) {
        resourceNames.stream().distinct().forEach(resource -> opsToAllow.forEach(op -> bindings.add(new AclBinding(new ResourcePattern(resourceType, resource, LITERAL), new AccessControlEntry(principal, host, op, ALLOW)))));
    }
    return bindings;
}

private List<AclBinding> createConsumerBindings(CreateConsumerAclDTO request) {
    List<AclBinding> bindings = new ArrayList<>();
    bindings.addAll(createAllowBindings(TOPIC, List.of(READ, DESCRIBE), request.getPrincipal(), request.getHost(), request.getTopicsPrefix(), request.getTopics()));
    bindings.addAll(createAllowBindings(GROUP, List.of(READ), request.getPrincipal(), request.getHost(), request.getConsumerGroupsPrefix(), request.getConsumerGroups()));
    return bindings;
}

private List<AclBinding> createProducerBindings(CreateProducerAclDTO request) {
    List<AclBinding> bindings = new ArrayList<>();
    bindings.addAll(createAllowBindings(TOPIC, List.of(WRITE, DESCRIBE, CREATE), request.getPrincipal(), request.getHost(), request.getTopicsPrefix(), request.getTopics()));
    bindings.addAll(createAllowBindings(TRANSACTIONAL_ID, List.of(WRITE, DESCRIBE), request.getPrincipal(), request.getHost(), request.getTransactionsIdPrefix(), Optional.ofNullable(request.getTransactionalId()).map(List::of).orElse(null)));
    if (Boolean.TRUE.equals(request.getIdempotent())) {
        bindings.addAll(createAllowBindings(CLUSTER, List.of(IDEMPOTENT_WRITE), request.getPrincipal(), request.getHost(), null,         List.of(Resource.CLUSTER_NAME)));
    }
    return bindings;
}

private List<AclBinding> createStreamAppBindings(CreateStreamAppAclDTO request) {
    List<AclBinding> bindings = new ArrayList<>();
    bindings.addAll(createAllowBindings(TOPIC, List.of(READ), request.getPrincipal(), request.getHost(), null, request.getInputTopics()));
    bindings.addAll(createAllowBindings(TOPIC, List.of(WRITE), request.getPrincipal(), request.getHost(), null, request.getOutputTopics()));
    bindings.addAll(createAllowBindings(GROUP, List.of(ALL), request.getPrincipal(), request.getHost(), request.getApplicationId(), null));
    bindings.addAll(createAllowBindings(TOPIC, List.of(ALL), request.getPrincipal(), request.getHost(), request.getApplicationId(), null));
    return bindings;
}

