private boolean isSwitchToStateEvent(AccessibilityEvent event, int expectedState, List<Integer> actualEvents) {
    if (!TestProtocol.SWITCHED_TO_STATE_MESSAGE.equals(event.getClassName()))
        return false;
    final Bundle parcel = (Bundle) event.getParcelableData();
    final int actualState = parcel.getInt(TestProtocol.STATE_FIELD);
    actualEvents.add(actualState);
    return actualState == expectedState;
}


