MutableWorldState getMutableWorldState(@Named("StateRoot") final Bytes32 stateRoot, final WorldStateStorageCoordinator worldStateStorageCoordinator, final WorldStatePreimageStorage worldStatePreimageStorage, final GenesisState genesisState, @Named("KeyValueStorageName") final String keyValueStorageName, final EvmConfiguration evmConfiguration) {
