        final MutableWorldState mutableWorldState = new ForestMutableWorldState(worldStateStorageCoordinator.worldStateKeyValueStorage(), worldStatePreimageStorage, evmConfiguration);
        genesisState.writeStateTo(mutableWorldState);
        return mutableWorldState;
    } else {
