private void assertArgument(PaimonCallStatement callStatement, int index, String expectedName, Object expectedValue, DataType expectedType) {
    if (expectedName == null) {
        PaimonCallArgument callArgument = callStatement.args().apply(index);
        assertCast(callArgument, PaimonPositionalArgument.class);
    } else {
        PaimonNamedArgument namedArgument = assertCast(callStatement.args().apply(index), PaimonNamedArgument.class);
        assertThat(namedArgument.name()).isEqualTo(expectedName);
    }
    assertThat(callStatement.args().apply(index).expr()).isEqualTo(Literal$.MODULE$.create(expectedValue, expectedType));
}

private <T> T assertCast(Object value, Class<T> expectedClass) {
    assertThat(value).isInstanceOf(expectedClass);
    return expectedClass.cast(value);
