    MergeFunction<KeyValue> aggregateFunction = AggregateMergeFunction.factory(options, Arrays.asList("k", "a", "b", "c", "d"), Arrays.asList(DataTypes.INT(), DataTypes.INT(), DataTypes.INT(), DataTypes.INT(), DataTypes.INT()), Collections.singletonList("k")).create();
