}

private String extractParameterSignature(String input) {
    int depth = 0, start = -1;
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c == '(') {
            if (depth++ == 0)
                start = i;
        } else if (c == ')' && --depth == 0 && start != -1) {
            return "(" + input.substring(start + 1, i) + ")";
        }
    }
    if (depth == 0) {
        return "";
    }
    return null;
}

