private boolean existsMessage(Connection connection, String queueName, String messageId) {
    final String EXISTS_MESSAGE = "SELECT EXISTS(SELECT 1 FROM queue_message WHERE queue_name = ? AND message_id = ?)";
    return query(connection, EXISTS_MESSAGE, q -> q.addParameter(queueName).addParameter(messageId).exists());
}

private void pushMessage(Connection connection, String queueName, String messageId, String payload, Integer priority, long offsetTimeInSecond) {
    createQueueIfNotExists(connection, queueName);
    String UPDATE_MESSAGE = "UPDATE queue_message SET payload=?, deliver_on=datetime(CURRENT_TIMESTAMP, '+' || ? || ' seconds') WHERE queue_name = ? AND message_id = ?";
    int rowsUpdated = query(connection, UPDATE_MESSAGE, q -> q.addParameter(payload).addParameter(offsetTimeInSecond).addParameter(queueName).addParameter(messageId).executeUpdate());
    if (rowsUpdated == 0) {
        String PUSH_MESSAGE = "INSERT INTO queue_message (deliver_on, queue_name, message_id, priority, offset_time_seconds, payload) VALUES (datetime(CURRENT_TIMESTAMP, '+' || ? || ' seconds'), ?,?,?,?,?) ON CONFLICT (queue_name,message_id) DO UPDATE SET payload=excluded.payload, deliver_on=excluded.deliver_on";
        execute(connection, PUSH_MESSAGE, q -> q.addParameter(offsetTimeInSecond).addParameter(queueName).addParameter(messageId).addParameter(priority).addParameter(offsetTimeInSecond).addParameter(payload).executeUpdate());
    }
}

private boolean removeMessage(Connection connection, String queueName, String messageId) {
    final String REMOVE_MESSAGE = "DELETE FROM queue_message WHERE queue_name = ? AND message_id = ?";
    return query(connection, REMOVE_MESSAGE, q -> q.addParameter(queueName).addParameter(messageId).executeDelete());
}

