public void formatAttribute(DOMAttr attr, int prevOffset, boolean singleAttribute, boolean useSettings, XMLFormattingConstraints parentConstraints, List<TextEdit> edits) {
        boolean alreadyIndented = false;
    if (useSettings) {
        int indentLevel = parentConstraints.getIndentLevel();
        if (isPreserveAttributeLineBreaks() && hasLineBreak(prevOffset, attr.getStart())) {
            replaceLeftSpacesWithIndentation(indentLevel + 1, prevOffset, attr.getStart(), true, edits);
            alreadyIndented = true;
        } else if (isSplitAttributes() && !singleAttribute) {
                        replaceLeftSpacesWithIndentation(indentLevel + getSplitAttributesIndentSize(), prevOffset, attr.getStart(), true, edits);
            alreadyIndented = true;
        }
    }
    if (!alreadyIndented) {
                int from = prevOffset;
        int to = attr.getStart();
        replaceLeftSpacesWithOneSpace(from, to, edits);
    }
        if (attr.hasDelimiter()) {
                int delimiterOffset = attr.getDelimiterOffset();
                int attrNameEnd = attr.getNodeAttrName().getEnd();
        removeLeftSpaces(attrNameEnd, delimiterOffset, edits);
        if (attr.getNodeAttrValue() != null) {
                        int attrValueStart = attr.getNodeAttrValue().getStart();
            removeLeftSpaces(delimiterOffset, attrValueStart, edits);
        }
        formatAttributeValue(attr, parentConstraints.getIndentLevel(), edits);
    }
        String originalValue = attr.getOriginalValue();
    if (originalValue != null) {
        if (originalValue.charAt(0) != getQuotationAsChar() && StringUtils.isQuote(originalValue.charAt(0))) {
            replaceQuoteWithPreferred(attr.getNodeAttrValue().getStart(), attr.getNodeAttrValue().getStart() + 1, edits);
        }
        if (originalValue.charAt(originalValue.length() - 1) != getQuotationAsChar() && StringUtils.isQuote(originalValue.charAt(originalValue.length() - 1))) {
            replaceQuoteWithPreferred(attr.getNodeAttrValue().getEnd() - 1, attr.getNodeAttrValue().getEnd(), edits);
        }
    }
}

