private int parseStringToAnInt(String s) {
    if (s == null)
        return 0;
    int result = 0;
    boolean negative = false;
    int radix = 10, i = 0, max = s.length();
    int limit, multmin, digit;
    if (max > 0) {
        if (s.charAt(0) == '-') {
            negative = true;
            limit = Integer.MIN_VALUE;
            i++;
        } else {
            limit = -Integer.MAX_VALUE;
        }
        multmin = limit / radix;
        if (i < max) {
            digit = Character.digit(s.charAt(i++), radix);
            if (digit < 0)
                return 0;
            else
                result = -digit;
        }
        while (i < max) {
                        digit = Character.digit(s.charAt(i++), radix);
            if (digit < 0)
                return 0;
            if (result < multmin)
                return 0;
            result *= radix;
            if (result < limit + digit)
                return 0;
            result -= digit;
        }
    } else {
        return 0;
    }
    if (negative) {
        if (i > 1)
            return result;
        else

            return 0;
    } else {
        return -result;
    }
}


