private String alphaValue(int value, int min, int max) {
    if (value <= 0) {
        return "" + value;
    }
    int range = max - min + 1;
    char last = (char) (((value - 1) % range) + min);
    if (value > range) {
        return alphaValue((value - 1) / range, min, max) + last;
    } else {
        return "" + last;
    }
}

