private Map<Bytes32, Bytes> collectTrieNodesToBeRequestedAfterRoot(final ForestWorldStateKeyValueStorage storage, final Bytes32 rootHash, final int maxNodes) {
    final Map<Bytes32, Bytes> trieNodes = new HashMap<>();
    TrieNodeDecoder.breadthFirstDecoder((location, hash) -> storage.getNodeData(hash), rootHash).filter(n -> !Objects.equals(n.getHash(), rootHash)).filter(Node::isReferencedByHash).limit(maxNodes).forEach((n) -> trieNodes.put(n.getHash(), n.getEncodedBytes()));
    return trieNodes;
}


private List<Bytes32> getFirstSetOfChildNodeRequests(final ForestWorldStateKeyValueStorage storage, final Bytes32 rootHash) {
    final List<Bytes32> hashesToRequest = new ArrayList<>();
    final Bytes rootNodeRlp = storage.getNodeData(rootHash).get();
    TrieNodeDecoder.decodeNodes(Bytes.EMPTY, rootNodeRlp).stream().filter(n -> !Objects.equals(n.getHash(), rootHash)).filter(Node::isReferencedByHash).forEach((n) -> hashesToRequest.add(n.getHash()));
    return hashesToRequest;
}

private void downloadAvailableWorldStateFromPeers(final int peerCount, final int accountCount, final int hashesPerRequest, final int maxOutstandingRequests) {
    downloadAvailableWorldStateFromPeers(peerCount, accountCount, hashesPerRequest, maxOutstandingRequests, this::respondFully);
}

private void respondFully(final List<RespondingEthPeer> peers, final WorldStateArchive remoteWorldStateArchive, final CompletableFuture<?> downloaderFuture) {
    final RespondingEthPeer.Responder responder = RespondingEthPeer.blockchainResponder(mock(Blockchain.class), remoteWorldStateArchive);
    respondUntilDone(peers, responder, downloaderFuture);
}

private void respondPartially(final List<RespondingEthPeer> peers, final WorldStateArchive remoteWorldStateArchive, final CompletableFuture<?> downloaderFuture) {
    final RespondingEthPeer.Responder fullResponder = RespondingEthPeer.blockchainResponder(mock(Blockchain.class), remoteWorldStateArchive, mock(TransactionPool.class));
    final RespondingEthPeer.Responder partialResponder = RespondingEthPeer.partialResponder(mock(Blockchain.class), remoteWorldStateArchive, mock(TransactionPool.class), ProtocolScheduleFixture.TESTING_NETWORK, .5f);
    final RespondingEthPeer.Responder emptyResponder = RespondingEthPeer.emptyResponder();
        for (int i = 0; i < 5; i++) {
        for (final RespondingEthPeer peer : peers) {
            peer.respond(partialResponder);
        }
        giveOtherThreadsAGo();
    }
        assertThat(downloaderFuture).isNotDone();
        for (int i = 0; i < 3; i++) {
        for (final RespondingEthPeer peer : peers) {
            peer.respond(emptyResponder);
        }
        giveOtherThreadsAGo();
    }
        assertThat(downloaderFuture).isNotDone();
    respondUntilDone(peers, fullResponder, downloaderFuture);
}

private void assertAccountsMatch(final WorldState worldState, final List<Account> expectedAccounts) {
    for (final Account expectedAccount : expectedAccounts) {
        final Account actualAccount = worldState.get(expectedAccount.getAddress());
        assertThat(actualAccount).isNotNull();
                assertThat(actualAccount.getNonce()).isEqualTo(expectedAccount.getNonce());
        assertThat(actualAccount.getCode()).isEqualTo(expectedAccount.getCode());
        assertThat(actualAccount.getBalance()).isEqualTo(expectedAccount.getBalance());
        final Map<Bytes32, AccountStorageEntry> actualStorage = actualAccount.storageEntriesFrom(Bytes32.ZERO, 500);
        final Map<Bytes32, AccountStorageEntry> expectedStorage = expectedAccount.storageEntriesFrom(Bytes32.ZERO, 500);
        assertThat(actualStorage).isEqualTo(expectedStorage);
    }
}

