private void respondUntilDone(final List<RespondingEthPeer> peers, final RespondingEthPeer.Responder responder, final CompletableFuture<?> result) {
    if (peers.size() == 1) {
                peers.get(0).respondWhileOtherThreadsWork(responder, () -> !result.isDone());
        return;
    }
    while (!result.isDone()) {
        for (final RespondingEthPeer peer : peers) {
            peer.respond(responder);
        }
        giveOtherThreadsAGo();
    }
}

private void giveOtherThreadsAGo() {
    LockSupport.parkNanos(200);
}

