    String deviceIdHash = "pZ9SP0USbXbejGFO6qx7x3JBjupJZVtw4RkFiNtJGqc=";
    String linkCodeHash = "wo5UcFFVSblZEd1KOUOl-dpJ5zpSr_Qsor1Eg4TzDRE";
    storage.createDeviceWithCode(process.getAppForTesting(), null, normalisedPhoneNumber, "linkCodeSalt", new PasswordlessCode(codeId, deviceIdHash, linkCodeHash, System.currentTimeMillis()));
    assertEquals(1, storage.getDevicesByPhoneNumber(process.getAppForTesting(), normalisedPhoneNumber).length);
    HashMap<String, String> map = new HashMap<>();
    map.put("phoneNumber", phoneNumber);
    JsonObject response = HttpRequestForTesting.sendGETRequest(process.getProcess(), "", "http:    assertEquals("OK", response.get("status").getAsString());
