    JsonArray jsonDeviceList = response.get("devices").getAsJsonArray();
    assertEquals(1, jsonDeviceList.size());
    checkDevice(jsonDeviceList, 0, null, normalisedPhoneNumber, deviceIdHash, new String[] { codeId });
