private AnnotationType combineAnnotationType(AnnotationType at1, AnnotationType at2) {
    if (at1 == AnnotationType.NONE) {
        return at2;
    } else if (at2 == AnnotationType.NONE) {
        return at1;
    } else if (at1 != at2) {
        return AnnotationType.BOTH;
    } else {
        return at1;
    }
}

