protected boolean shouldUsePostMergeRules(final BlockHeader header, final ProtocolContext context) {
    if (context.getConsensusContext(MergeContext.class).getFinalized().isPresent()) {
                return true;
    }
    Optional<Difficulty> parentChainTotalDifficulty = context.getBlockchain().getTotalDifficultyByHash(header.getParentHash());
    Difficulty configuredTotalTerminalDifficulty = context.getConsensusContext(MergeContext.class).getTerminalTotalDifficulty();
    if (parentChainTotalDifficulty.isEmpty()) {
        LOG.warn("unable to get total difficulty, parent {} not found", header.getParentHash());
        return false;
    }
    if (isTerminalProofOfWorkBlock(header, context)) {
                return false;
    }
    if (parentChainTotalDifficulty.get().add(header.getDifficulty() == null ? Difficulty.ZERO : header.getDifficulty()).greaterOrEqualThan(configuredTotalTerminalDifficulty)) {
        return true;
    } else {
                return false;
    }
}
