public static ProtocolSchedule create(final GenesisConfigOptions config, final boolean isRevertReasonEnabled, final MiningConfiguration miningConfiguration, final BadBlockManager badBlockManager, final boolean isParallelTxProcessingEnabled, final boolean isBlockAccessListEnabled, final MetricsSystem metricsSystem, final EvmConfiguration evmConfiguration) {
    Map<Long, Function<ProtocolSpecBuilder, ProtocolSpecBuilder>> postMergeModifications = new HashMap<>();
    postMergeModifications.put(0L, (specBuilder) -> MergeProtocolSchedule.applyParisSpecificModifications(specBuilder, config.getChainId(), miningConfiguration, evmConfiguration));
    unapplyModificationsFromShanghaiOnwards(config, postMergeModifications);
    return new ProtocolScheduleBuilder(config, Optional.of(DEFAULT_CHAIN_ID), new ProtocolSpecAdapters(postMergeModifications), isRevertReasonEnabled, evmConfiguration, miningConfiguration, badBlockManager, isParallelTxProcessingEnabled, isBlockAccessListEnabled, metricsSystem).createProtocolSchedule();
}


private static ProtocolSpecBuilder applyParisSpecificModifications(final ProtocolSpecBuilder specBuilder, final Optional<BigInteger> chainId, final MiningConfiguration miningConfiguration, final EvmConfiguration evmConfiguration) {
    return specBuilder.evmBuilder((gasCalculator, jdCacheConfig) -> MainnetEVMs.paris(gasCalculator, chainId.orElse(BigInteger.ZERO), evmConfiguration)).blockHeaderValidatorBuilder(MergeProtocolSchedule::getBlockHeaderValidator).blockReward(Wei.ZERO).difficultyCalculator((a, b) -> BigInteger.ZERO).skipZeroBlockRewards(true).isPoS(true).slotDuration(Duration.ofSeconds(miningConfiguration.getUnstable().getPosSlotDuration())).hardforkId(PARIS);
}

private static BlockHeaderValidator.Builder getBlockHeaderValidator(final FeeMarket feeMarket, final GasCalculator gasCalculator, final GasLimitCalculator gasLimitCalculator) {
    return MergeValidationRulesetFactory.mergeBlockHeaderValidator(feeMarket);
}

private static void unapplyModificationsFromShanghaiOnwards(final GenesisConfigOptions config, final Map<Long, Function<ProtocolSpecBuilder, ProtocolSpecBuilder>> postMergeModifications) {
        if (!config.getForkBlockTimestamps().isEmpty()) {
        postMergeModifications.put(config.getForkBlockTimestamps().getFirst(), Function.identity());
    }
}
