@Override
public void putPayloadById(final PayloadWrapper newPayload) {
    final var newBlockWithReceipts = newPayload.blockWithReceipts();
    final var newBlockValue = newPayload.blockValue();
    synchronized (blocksInProgress) {
        final Optional<PayloadWrapper> maybeCurrBestPayload = retrievePayloadById(newPayload.payloadIdentifier());
        maybeCurrBestPayload.ifPresent(currBestPayload -> {
            if (newBlockValue.greaterThan(currBestPayload.blockValue())) {
                LOG.atInfo().setMessage("New proposal for payloadId {} {} is better than the previous one by {}").addArgument(newPayload.payloadIdentifier()).addArgument(() -> logBlockProposal(newBlockWithReceipts.getBlock(), newBlockValue)).addArgument(() -> newBlockValue.subtract(currBestPayload.blockValue()).toHumanReadableString()).log();
                blocksInProgress.removeAll(streamPayloadsById(newPayload.payloadIdentifier()).toList());
                logCurrentBestBlock(newPayload);
            }
        });
        blocksInProgress.add(newPayload);
    }
}

private void logCurrentBestBlock(final PayloadWrapper payloadWrapper) {
    if (LOG.isDebugEnabled()) {
        final Block block = payloadWrapper.blockWithReceipts().getBlock();
        final float gasUsedPerc = 100.0f * block.getHeader().getGasUsed() / block.getHeader().getGasLimit();
        final int txsNum = block.getBody().getTransactions().size();
        LOG.debug("Current best proposal for block {}: txs {}, gas used {}%, reward {}", block.getHeader().getNumber(), txsNum, String.format("%1.2f", gasUsedPerc), payloadWrapper.blockValue().toHumanReadableString());
    }
}

@Override
public Optional<PayloadWrapper> retrievePayloadById(final PayloadIdentifier payloadId) {
    synchronized (blocksInProgress) {
        return streamPayloadsById(payloadId).max(Comparator.comparing(PayloadWrapper::blockValue));
    }
}

private Stream<PayloadWrapper> streamPayloadsById(final PayloadIdentifier payloadId) {
    return blocksInProgress.stream().filter(z -> z.payloadIdentifier().equals(payloadId));
}

private String logBlockProposal(final Block block, final Wei value) {
    return "block " + block.toLogString() + " gas used " + block.getHeader().getGasUsed() + " transactions " + block.getBody().getTransactions().size() + " reward " + value.toHumanReadableString();
}

