public ProtocolSpec getByBlockHeaderWithTransitionReorgHandling(final ProcessableBlockHeader blockHeader) {
        if (mergeContext.getFinalized().isEmpty()) {
                if (!mergeContext.isPostMerge()) {
            LOG.atDebug().setMessage("for {} returning a pre-merge schedule because we are not post-merge").addArgument(blockHeader::toLogString).log();
            return getPreMergeSchedule().getByBlockHeader(blockHeader);
        }
                Difficulty parentDifficulty = protocolContext.getBlockchain().getTotalDifficultyByHash(blockHeader.getParentHash()).orElse(Difficulty.ZERO);
        Difficulty thisDifficulty = parentDifficulty.add(blockHeader.getDifficulty());
        Difficulty terminalDifficulty = mergeContext.getTerminalTotalDifficulty();
        LOG.atDebug().setMessage(" block {} ttd is: {}, parent total diff is: {}, this total diff is: {}").addArgument(blockHeader::toLogString).addArgument(terminalDifficulty).addArgument(parentDifficulty).addArgument(thisDifficulty).log();
                if (thisDifficulty.lessThan(terminalDifficulty) || TransitionUtils.isTerminalProofOfWorkBlock(blockHeader, protocolContext)) {
            LOG.atDebug().setMessage("returning a pre-merge schedule because block {} is pre-merge or TTD").addArgument(blockHeader::toLogString).log();
            return getPreMergeSchedule().getByBlockHeader(blockHeader);
        }
    }
        LOG.atDebug().setMessage(" for {} returning a post-merge schedule").addArgument(blockHeader::toLogString).log();
    return getPostMergeSchedule().getByBlockHeader(blockHeader);
}

