public static boolean isTerminalProofOfWorkBlock(final ProcessableBlockHeader header, final ProtocolContext context) {
    Difficulty headerDifficulty = Optional.ofNullable(header.getDifficulty()).orElse(Difficulty.ZERO);
    Difficulty currentChainTotalDifficulty = context.getBlockchain().getTotalDifficultyByHash(header.getParentHash()).orElse(Difficulty.ZERO);
    final MergeContext consensusContext = context.getConsensusContext(MergeContext.class);
        if (consensusContext.isPostMergeAtGenesis()) {
        return false;
    }
    if (currentChainTotalDifficulty.isZero()) {
        LOG.atInfo().setMessage("Total difficulty unavailable for {} (parent: {}). Expected during transition from Clique/PoW to PoS or at merge-at-genesis.").addArgument(header::toLogString).addArgument(header::getParentHash).log();
    }
    Difficulty configuredTotalTerminalDifficulty = consensusContext.getTerminalTotalDifficulty();
    if (currentChainTotalDifficulty.add(headerDifficulty).greaterOrEqualThan(    configuredTotalTerminalDifficulty) && currentChainTotalDifficulty.lessThan(    configuredTotalTerminalDifficulty)) {
        return true;
    }
        return header.getNumber() == 0L && header.getDifficulty().greaterOrEqualThan(configuredTotalTerminalDifficulty);
}
