    final GenesisConfigOptions config = GenesisConfig.fromConfig(jsonInput).getConfigOptions();
    final ProtocolSchedule protocolSchedule = MergeProtocolSchedule.create(config, false, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem(), EvmConfiguration.DEFAULT);
    final ProtocolSpec homesteadSpec = protocolSchedule.getByBlockHeader(blockHeader(1));
