}

@Test
public void mergeSpecificModificationsAreUnappliedForShanghai() {
    final GenesisConfigOptions config = GenesisConfig.mainnet().getConfigOptions();
    final ProtocolSchedule protocolSchedule = MergeProtocolSchedule.create(config, false, MiningConfiguration.MINING_DISABLED, new BadBlockManager(), false, false, new NoOpMetricsSystem(), EvmConfiguration.DEFAULT);
    final long lastParisBlockNumber = 17034869L;
    final ProtocolSpec parisSpec = protocolSchedule.getByBlockHeader(blockHeader(lastParisBlockNumber));
    final ProtocolSpec shanghaiSpec = protocolSchedule.getByBlockHeader(new BlockHeaderTestFixture().timestamp(1681338455).buildHeader());
    assertThat(parisSpec.getHardforkId()).isEqualTo(PARIS);
    assertThat(shanghaiSpec.getHardforkId()).isEqualTo(SHANGHAI);
        final int PUSH0 = 0x5f;
    assertThat(parisSpec.getEvm().getOperationsUnsafe()[PUSH0]).isInstanceOf(InvalidOperation.class);
    assertThat(shanghaiSpec.getEvm().getOperationsUnsafe()[PUSH0]).isInstanceOf(Push0Operation.class);
    assertProofOfStakeConfigIsEnabled(parisSpec);
    assertProofOfStakeConfigIsEnabled(shanghaiSpec);
}

