@Override
public QbftBlock createSealedBlock(final QbftBlock block, final int roundNumber, final Collection<SECPSignature> commitSeals) {
    final Block besuBlock = AdaptorUtil.toBesuBlock(block);
    final QbftBlockHeader initialHeader = block.getHeader();
    final BftExtraData initialExtraData = bftExtraDataCodec.decode(AdaptorUtil.toBesuBlockHeader(initialHeader));
    final BftExtraData sealedExtraData = new BftExtraData(initialExtraData.getVanityData(), commitSeals, initialExtraData.getVote(), roundNumber, initialExtraData.getValidators());
    final BlockHeader sealedHeader = BlockHeaderBuilder.fromHeader(AdaptorUtil.toBesuBlockHeader(initialHeader)).extraData(bftExtraDataCodec.encode(sealedExtraData)).blockHeaderFunctions(BftBlockHeaderFunctions.forOnchainBlock(bftExtraDataCodec)).buildBlockHeader();
    final Block sealedBesuBlock = new Block(sealedHeader, besuBlock.getBody());
    return new QbftBlockAdaptor(sealedBesuBlock);
}
