public void verifyEventReceived(final Hash expectedTransaction, final int expectedOccurrences) {
    WaitUtils.waitFor(() -> {
        assertThat(connection.getSubscriptionEvents()).isNotEmpty();
        final List<SubscriptionEvent> events = connection.getSubscriptionEvents();
        int occurrences = 0;
        for (final SubscriptionEvent event : events) {
            if (matches(expectedTransaction, event)) {
                occurrences++;
            }
        }
        assertThat(occurrences).as("Expecting: %s occurrences, but found: %s", expectedOccurrences, occurrences).isEqualTo(expectedOccurrences);
    });
}

private boolean isExpectedSubscription(final SubscriptionEvent event) {
    final Map<String, String> params = event.getParams();
    return params.size() == 2 && params.containsKey("subscription") && value.equals(params.get("subscription"));
}

private boolean isExpectedTransaction(final Hash expectedTransaction, final SubscriptionEvent event) {
    final Map<String, String> params = event.getParams();
    final String result = params.get("result");
    return params.containsKey("result") && expectedTransaction.toString().equals(result) && result.matches(SIXTY_FOUR_HEX_PATTERN);
}

