@Override
public boolean equals(final Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    final Subscription that = (Subscription) o;
    return Objects.equals(subscriptionId, that.subscriptionId) && subscriptionType == that.subscriptionType;
}

