private boolean matches(final Hash expectedTransaction, final SubscriptionEvent event) {
    return isEthSubscription(event) && isExpectedSubscription(event) && isExpectedTransaction(expectedTransaction, event);
}

private boolean isEthSubscription(final SubscriptionEvent event) {
    return "2.0".equals(event.getVersion()) && "eth_subscription".equals(event.getMethod()) && event.getParams() != null;
}
