@Override
public Optional<FastSyncState> selectNewPivotBlock() {
    final BftContext bftContext = protocolContext.getConsensusContext(BftContext.class);
    final ValidatorProvider validatorProvider = bftContext.getValidatorProvider();
        Optional<EthPeer> bestPeer = selectBestPeer();
    if (bestPeer.isPresent()) {
                if (bestPeer.get().chainState().getEstimatedHeight() <= syncConfig.getSyncPivotDistance()) {
            LOG.info("Best peer for sync found but chain height hasn't reached minimum sync pivot distance {}, exiting sync process", syncConfig.getSyncPivotDistance());
            throw new NoSyncRequiredException();
        }
        return bestPeer.flatMap(this::fromBestPeer);
    } else {
                if (weAreAValidator(validatorProvider) && validatorProvider.getValidatorsAtHead().size() == 1) {
            LOG.info("This node is the only BFT validator, exiting sync process");
            throw new NoSyncRequiredException();
        }
                if (blockHeader.getNumber() == 0) {
            final AtomicInteger peerValidatorCount = new AtomicInteger();
            final AtomicBoolean peerAtOurGenesisBlock = new AtomicBoolean();
            ethContext.getEthPeers().streamAllPeers().map(EthPeerImmutableAttributes::ethPeer).forEach(peer -> {
                                if (peer.chainState().getBestBlock().getHash().equals(blockHeader.getBlockHash())) {
                    peerAtOurGenesisBlock.set(true);
                }
                if (!peer.getConnection().isDisconnected() && validatorProvider.getValidatorsAtHead().contains(peer.getConnection().getPeerInfo().getAddress())) {
                    peerValidatorCount.getAndIncrement();
                }
            });
            if (weAreAValidator(validatorProvider) && peerValidatorCount.get() >= syncConfig.getSyncMinimumPeerCount() && peerAtOurGenesisBlock.get()) {
                                LOG.info("Peered with {} validators but no best peer found to sync from and their current block hash matches our genesis block. Assuming new BFT chain, exiting snap-sync", peerValidatorCount.get());
                throw new NoSyncRequiredException();
            }
        }
    }
    return Optional.empty();
}
