protected Map<String, JsonRpcMethod> create() {
    final BlockchainQueries blockchainQueries = new BlockchainQueries(protocolSchedule, context.getBlockchain(), context.getWorldStateArchive(), miningConfiguration);
    final BftContext bftContext = context.getConsensusContext(BftContext.class);
