public Collection<Address> getValidators(final long blockNumber, final Address contractAddress) {
    return callFunction(blockNumber, getValidatorsFunction, contractAddress).map(this::parseGetValidatorsResult).orElseThrow(() -> new IllegalStateException(CONTRACT_ERROR_MSG));
}

@SuppressWarnings({ "rawtypes", "unchecked" })
private Collection<Address> parseGetValidatorsResult(final TransactionSimulatorResult result) {
    final List<Type> resultDecoding = decodeResult(result, getValidatorsFunction);
    final List<org.web3j.abi.datatypes.Address> addresses = (List<org.web3j.abi.datatypes.Address>) resultDecoding.get(0).getValue();
    return addresses.stream().map(a -> Address.fromHexString(a.getValue())).collect(Collectors.toList());
}

private Optional<TransactionSimulatorResult> callFunction(final long blockNumber, final Function function, final Address contractAddress) {
    final Bytes payload = Bytes.fromHexString(FunctionEncoder.encode(function));
    final CallParameter callParams = ImmutableCallParameter.builder().to(contractAddress).input(payload).build();
    final TransactionValidationParams transactionValidationParams = TransactionValidationParams.transactionSimulatorAllowExceedingBalance();
    return transactionSimulator.process(callParams, transactionValidationParams, OperationTracer.NO_TRACING, blockNumber);
}

@SuppressWarnings("rawtypes")
private List<Type> decodeResult(final TransactionSimulatorResult result, final Function function) {
    if (result.isSuccessful()) {
        final List<Type> decodedList = FunctionReturnDecoder.decode(result.result().getOutput().toHexString(), function.getOutputParameters());
        if (decodedList.isEmpty()) {
            throw new IllegalStateException("Unexpected empty result from validator smart contract call");
        }
        return decodedList;
    } else {
        throw new IllegalStateException("Failed validator smart contract call: " + result.getValidationResult());
    }
}
