public static <T> T get(String key, Class<T> clazz) {
    Cache<String, String> myCache = cacheManager.getCache(CACHE, String.class, String.class);
    String value = myCache.get(key);
    if (!StringUtils.isEmpty(value)) {
        return JSON.parseObject(value, clazz);
    }
    return null;
}

public static <T> List<T> getList(String key, Class<T> clazz) {
    Cache<String, String> myCache = cacheManager.getCache(CACHE, String.class, String.class);
    String value = myCache.get(key);
    if (!StringUtils.isEmpty(value)) {
        return JSON.parseArray(value, clazz);
    }
    return null;
}

public static <T> T get(String key, Class<T> clazz, Function<Object, Boolean> refresh, Function<Object, T> function) {
    T t;
    if (refresh.apply(key)) {
        t = function.apply(key);
        put(key, t);
    } else {
        t = get(key, clazz);
        if (t == null) {
            t = function.apply(key);
            put(key, t);
        }
    }
    return t;
}

public static <T> List<T> getList(String key, Class<T> clazz, Function<Object, Boolean> refresh, Function<Object, List<T>> function) {
    List<T> t;
    if (refresh.apply(key)) {
        t = function.apply(key);
        put(key, t);
    } else {
        t = getList(key, clazz);
        if (t == null) {
            t = function.apply(key);
            put(key, t);
        }
    }
    return t;
}

public static void put(String s, Object value) {
    Cache<String, String> myCache = cacheManager.getCache(CACHE, String.class, String.class);
    myCache.put(s, JSON.toJSONString(value));
}

public static void close() {
    cacheManager.close();
}
