@Override
public ListResult<Schema> querySchema(SchemaQueryParam param) {
    List<Schema> schemas = CacheManage.getList(getSchemasKey(param.getDataSourceId(), param.getDataBaseName()), Schema.class, (key) -> param.isRefresh(), (key) -> {
        Connection connection = param.getConnection() == null ? Chat2DBContext.getConnection() : param.getConnection();
