@Test
public void coreGenerator() {
    HikariDataSource dataSource = new HikariDataSource();
    String environment = StringUtils.defaultString(System.getProperty("spring.profiles.active"), "dev");
    if ("dev".equalsIgnoreCase(environment)) {
        dataSource.setJdbcUrl("jdbc:h2:file:~/.chat2db/db/chat2db_dev;MODE=MYSQL");
    } else if ("test".equalsIgnoreCase(environment)) {
        dataSource.setJdbcUrl("jdbc:h2:file:~/.chat2db/db/chat2db_test;MODE=MYSQL");
    } else {
        dataSource.setJdbcUrl("jdbc:h2:~/.chat2db/db/chat2db;MODE=MYSQL;FILE_LOCK=NO");
    }
    dataSource.setDriverClassName("org.h2.Driver");
    dataSource.setIdleTimeout(60000);
    dataSource.setAutoCommit(true);
    dataSource.setMaximumPoolSize(500);
    dataSource.setMinimumIdle(1);
    dataSource.setMaxLifetime(60000 * 10);
    dataSource.setConnectionTestQuery("SELECT 1");
    this.dataSource = dataSource;
        doGenerator(Lists.newArrayList("TASK"));
}

private void doGenerator(List<String> tableList) {
        String outputDir = System.getProperty("user.dir") + "/../chat2db-server-domain/chat2db-server-domain-repository/src/main" + "/java";
    String xmlDir = System.getProperty("user.dir") + "/../chat2db-server-domain/chat2db-server-domain-repository/src/main" + "/resources/mapper";
        Map<OutputFile, String> pathInfo = new HashMap<>();
    pathInfo.put(OutputFile.service, null);
    pathInfo.put(OutputFile.serviceImpl, null);
    pathInfo.put(OutputFile.xml, xmlDir);
    pathInfo.put(OutputFile.controller, null);
    FastAutoGenerator.create(new DataSourceConfig.Builder(dataSource).typeConvert(new MySqlTypeConvert())).globalConfig(builder -> {
                builder.author("chat2db").disableOpenDir().dateType(DateType.ONLY_DATE).outputDir(outputDir);
    }).packageConfig(builder -> {
                builder.parent("ai.chat2db.server.domain.repository").entity("entity").pathInfo(pathInfo).mapper("mapper");
    }).strategyConfig(builder -> {
                builder.addInclude(tableList).entityBuilder().formatFileName("%sDO").enableFileOverride().enableLombok().mapperBuilder().enableFileOverride();
    }).templateEngine(    new FreemarkerTemplateEngine()).execute();
}
